mapper.select:
SELECT dict1.DICT_ITEM_VAL_CNNAME tradeMarket,/*交易市场*/ T4.ASSET_TYPE assetType, decode(T4.ASSET_TYPE,#{assetBond},SUBSTR(TRIM(T3.FINPROD_MARKET_ID), 0, LENGTH(TRIM(T3.FINPROD_MARKET_ID)) - 3),#{ASSET_TYPE_08},dict2.DICT_ITEM_VAL_CNNAME,null) finprodMarketId,/*证券代码：资产代码/期限品种*/ decode(T4.ASSET_TYPE,#{assetBond},dict3.DICT_ITEM_VAL_CNNAME,#{ASSET_TYPE_08},dict4.DICT_ITEM_VAL_CNNAME,null) ps,/*委托方向：交易方向*/ trunc(( CASE WHEN T4.ASSET_TYPE = #{assetBond} THEN T1.ENTRUST_NUM*100 ELSE NVL(T1.ENTRUST_AMT,T1.ENTRUST_NUM) END)/100) entrustAmt,/*指令数量：券面总额/委托金额*/ trunc(decode(T4.ASSET_TYPE,'F01',decode(T1.PRICE_MODEL,'PRM03',0,decode(fpd.IS_NETPRICE,'Y',t1.price,t1.price)),'F07',decode(T1.PRICE_MODEL,'PRM03',0,t1.price*100),null),3) price,/*指令价格*/ dict5.DICT_ITEM_VAL_CNNAME priceModel,/*价格模式*/ dict6.DICT_ITEM_VAL_CNNAME invAim,/*投资类型：投资目的*/ pb_prd.pb_id finprodId,/*产品编号：产品*/ pb_ptl.pb_id portfolioId,/*账户编号：子组合*/ T1.ENTRUST_ID entrustId/*记录号:委托代码*/ FROM ETR_ENTRUST T1 LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD fpd on fpd.finprod_id = T3.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN SYS_PAGE_DICTLIST dict1 ON dict1.DICT_ID = 'TRADE_PLACE' AND dict1.PAGE_ID = 'EtrInvestAllInfoPB' AND dict1.dict_item_val=T1.TRADE_MARKET LEFT JOIN SYS_PAGE_DICTLIST dict2 ON dict2.DICT_ID = 'TERM_TYPE_REBACK' AND dict2.PAGE_ID = 'EtrInvestAllInfoPB' AND dict2.dict_item_val=T4.TERM_TYPE LEFT JOIN SYS_PAGE_DICTLIST dict3 ON dict3.DICT_ID = 'PS' AND dict3.PAGE_ID = 'EtrInvestAllInfoPB' AND dict3.dict_item_val=T1.PS LEFT JOIN SYS_PAGE_DICTLIST dict4 ON dict4.DICT_ID = 'BACK_LEND_DIRECTION' AND dict4.PAGE_ID = 'EtrInvestAllInfoPB' AND dict4.dict_item_val=T1.PS LEFT JOIN SYS_PAGE_DICTLIST dict5 ON dict5.DICT_ID = 'PRICE_MODEL' AND dict5.PAGE_ID = 'EtrInvestAllInfoPB' AND dict5.dict_item_val=T1.PRICE_MODEL LEFT JOIN SYS_PAGE_DICTLIST dict6 ON dict6.DICT_ID = 'INV_AIM' AND dict6.PAGE_ID = 'EtrInvestAllInfoPB' AND dict6.dict_item_val=T1.INV_AIM LEFT JOIN trd_pb_relation pb_prd ON pb_prd.prd_portfolio_id = T1.PORTFOLIO_ID and pb_prd.factor_type='0' LEFT JOIN trd_pb_relation pb_ptl ON pb_ptl.prd_portfolio_id = T1.PORTFOLIO_ID and pb_ptl.factor_type='1'
and (T1.ENTRUST_ID in
null) or T1.ENTRUST_ID in (
#{item}
)
ORDER BY T1.vdate DESC

choose.when:
SELECT DISTINCT TO_CHAR(EE.ENTRUST_DATE,'yyyy-MM-dd') entrustDateStr,/*交易日期*/ FP.FINPROD_MARKET_ID finprodMarketId,/*债券代码*/ FP.FINPROD_ABBR finprodAbbr,/*债券简称*/ DECODE(EE.PS,'T01',MCP.COUNTER_NAME,PP.PORTFOLIO_NAME)saler,/*卖出方*/ DECODE(EE.PS,'T01',PP.PORTFOLIO_NAME,MCP.COUNTER_NAME)buyer,/*买入方*/ EE.ENTRUST_NUM/100 entrustNum,/*交易面额*/ EE.PRICE price,/*交易净价*/ MBVI.NETPRICE valuePrice,/*估值净价*/ (EE.PRICE-MBVI.NETPRICE)*100/MBVI.NETPRICE deviation,/*价格偏离度*/ EE.REMARK remark, /*备注*/ SWBN1.OPINIONS jbyj,/*经办意见*/ CASE WHEN SWBN1.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN1.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END jbrq,/*经办审批日期*/ SWBN2.OPINIONS fhyj,/*复核意见*/ CASE WHEN SWBN2.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN2.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END fhrq,/*复核审批日期*/ SWBN3.OPINIONS fkyj,/*风控意见*/ CASE WHEN SWBN3.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN3.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END fkrq,/*风控审批日期*/ SWBN4.OPINIONS fgyj,/*分管负责人意见*/ CASE WHEN SWBN4.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN4.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END fgrq,/*分管负责人审批日期*/ SWBN5.OPINIONS zgyj,/*资管部意见*/ CASE WHEN SWBN5.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN5.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END zgrq/*资管部审批日期*/ FROM ETR_ENTRUST EE LEFT JOIN ETR_ENTRUST_ADD EEA ON EE.ENTRUST_ID = EEA.ENTRUST_ID LEFT JOIN FIN_PRODUCT FP ON EE.FINPROD_ID = FP.FINPROD_ID LEFT JOIN MST_BOND_VALUATION_INFO MBVI ON FP.FINPROD_MARKET_ID = MBVI.SEC_ID LEFT JOIN MST_COUNTER_PARTY MCP ON EE.COUNTER_ID = MCP.COUNTER_ID LEFT JOIN PTL_PORTFOLIO PP ON EE.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN (SELECT A.WORKFLOW_ID,A.TRADE_ID,ROW_NUMBER() OVER (PARTITION BY A.TRADE_ID ORDER BY A.UPDATE_TIME DESC) NUM FROM SYS_WFL_BUSINESS_LIST A) SWBL ON EE.ENTRUST_ID = SWBL.TRADE_ID AND NUM = 1 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN1 ON SWBL.WORKFLOW_ID = SWBN1.WORKFLOW_ID AND SWBN1.HIS_NO = 1 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN2 ON SWBL.WORKFLOW_ID = SWBN2.WORKFLOW_ID AND SWBN2.HIS_NO = 2 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN3 ON SWBL.WORKFLOW_ID = SWBN3.WORKFLOW_ID AND SWBN3.HIS_NO = 3 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN4 ON SWBL.WORKFLOW_ID = SWBN4.WORKFLOW_ID AND SWBN4.HIS_NO = 4 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN5 ON SWBL.WORKFLOW_ID = SWBN5.WORKFLOW_ID AND SWBN5.HIS_NO = 5 INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON EE.PORTFOLIO_ID = PPA.PORTFOLIO_ID WHERE EEA.ASSET_TYPE = 'F01'
AND PPA.USER_ID = #{userId,jdbcType=VARCHAR}
AND (EE.ENTRUST_ID IN
null) OR EE.ENTRUST_ID IN (
#{item,jdbcType=VARCHAR}
or EE.ENTRUST_ID IN
null) OR EE.ENTRUST_ID IN (
