)

SELECT EE.ENTRUST_ID, TO_CHAR(EE.ENTRUST_DATE,'yyyy-MM-dd') entrustDateStr,/*交易日期*/ PP.PORTFOLIO_NAME portfolioName,/*组合名称*/ SDL.ITEM_VALUE ps,/*交易方向*/ EEA.TERM_DAYS term,/*回购期限*/ EE.PRICE*100 price,/*回购利率*/ EE.ENTRUST_AMT/10000 entrustAmt,/*交易金额*/ MCP.COUNTER_NAME counterName,/*交易对手*/ (SELECT WM_CONCAT(FP1.FINPROD_MARKET_ID) FROM ETR_PLEDGE EP LEFT JOIN FIN_PRODUCT FP1 ON EP.FINPROD_ID = FP1.FINPROD_ID WHERE EE.ENTRUST_ID = EP.ENTRUST_ID) repSecId,/*质押券*/ (SELECT WM_CONCAT(EP.PLEDGE_RATIO*100) FROM ETR_PLEDGE EP WHERE EE.ENTRUST_ID = EP.ENTRUST_ID) conRatio,/*折算比列*/ EE.REMARK remark, /*备注*/ SWBN1.OPINIONS jbyj,/*经办意见*/ CASE WHEN SWBN1.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN1.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END jbrq,/*经办审批日期*/ SWBN2.OPINIONS fhyj,/*复核意见*/ CASE WHEN SWBN2.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN2.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END fhrq,/*复核审批日期*/ SWBN3.OPINIONS fkyj,/*风控意见*/ CASE WHEN SWBN3.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN3.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END fkrq,/*风控审批日期*/ SWBN4.OPINIONS fgyj,/*分管负责人意见*/ CASE WHEN SWBN4.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN4.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END fgrq,/*分管负责人审批日期*/ SWBN5.OPINIONS zgyj,/*资管部意见*/ CASE WHEN SWBN5.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN5.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END zgrq/*资管部审批日期*/ FROM ETR_ENTRUST EE LEFT JOIN ETR_ENTRUST_ADD EEA ON EE.ENTRUST_ID = EEA.ENTRUST_ID LEFT JOIN FIN_PRODUCT FP ON EE.FINPROD_ID = FP.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY MCP ON EE.COUNTER_ID = MCP.COUNTER_ID LEFT JOIN PTL_PORTFOLIO PP ON EE.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN SYS_DATADICT_LIST SDL ON SDL.ITEM_CODE = EE.PS AND SDL.DICT_CODE = 'PS' LEFT JOIN (SELECT A.WORKFLOW_ID,A.TRADE_ID,ROW_NUMBER() OVER (PARTITION BY A.TRADE_ID ORDER BY A.UPDATE_TIME DESC) NUM FROM SYS_WFL_BUSINESS_LIST A) SWBL ON EE.ENTRUST_ID = SWBL.TRADE_ID AND NUM = 1 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN1 ON SWBL.WORKFLOW_ID = SWBN1.WORKFLOW_ID AND SWBN1.HIS_NO = 1 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN2 ON SWBL.WORKFLOW_ID = SWBN2.WORKFLOW_ID AND SWBN2.HIS_NO = 2 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN3 ON SWBL.WORKFLOW_ID = SWBN3.WORKFLOW_ID AND SWBN3.HIS_NO = 3 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN4 ON SWBL.WORKFLOW_ID = SWBN4.WORKFLOW_ID AND SWBN4.HIS_NO = 4 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN5 ON SWBL.WORKFLOW_ID = SWBN5.WORKFLOW_ID AND SWBN5.HIS_NO = 5 INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON EE.PORTFOLIO_ID = PPA.PORTFOLIO_ID WHERE EEA.ASSET_TYPE = 'F07'
AND PPA.USER_ID = #{userId,jdbcType=VARCHAR}
AND (EE.ENTRUST_ID IN
null) OR EE.ENTRUST_ID IN (
