SELECT TO_CHAR(EE.ENTRUST_DATE,'yyyy-MM-dd') entrustDateStr,/*交易日期*/ EE.PORTFOLIO_ID portfolioId,/*组合代码*/ PP.PORTFOLIO_NAME portfolioName,/*组合名称*/ EEA.SEC_ACCT_ID secAcctId,/*证券账户*/ SDL2.ITEM_VALUE assetType,/*资产类型*/ FP.FINPROD_MARKET_ID finprodMarketId,/*资产代码*/ FP.FINPROD_NAME finprodAbbr,/*债券简称*/ SDL1.ITEM_VALUE ps,/*交易方向*/ SDL3.ITEM_VALUE tradeMarket,/*交易场所*/ EEA.SETTLE_SPREED settleSpreed,/*清算速度*/ (CASE WHEN EEA.ASSET_TYPE = #{assetBond} THEN EE.ENTRUST_NUM*100 ELSE NVL(EE.ENTRUST_AMT,EE.ENTRUST_NUM*100) END) entrustAmt, /*指令金额*/ SWBN1.OPINIONS jbyj,/*经办意见*/ CASE WHEN SWBN1.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN1.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END jbrq,/*经办审批日期*/ SWBN2.OPINIONS fhyj,/*复核意见*/ CASE WHEN SWBN2.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN2.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END fhrq,/*复核审批日期*/ SWBN3.OPINIONS fkyj,/*风控意见*/ CASE WHEN SWBN3.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN3.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END fkrq,/*风控审批日期*/ SWBN4.OPINIONS fgyj,/*分管负责人意见*/ CASE WHEN SWBN4.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN4.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END fgrq,/*分管负责人审批日期*/ SWBN5.OPINIONS zgyj,/*资管部意见*/ CASE WHEN SWBN5.CREATE_TIME IS NOT NULL THEN TO_CHAR(SWBN5.CREATE_TIME,'yyyy"年"MM"月"dd"日"') ELSE ' 年 月 日' END zgrq/*资管部审批日期*/ FROM ETR_ENTRUST EE LEFT JOIN ETR_ENTRUST_ADD EEA ON EE.ENTRUST_ID = EEA.ENTRUST_ID LEFT JOIN FIN_PRODUCT FP ON EE.FINPROD_ID = FP.FINPROD_ID LEFT JOIN SYS_DATADICT_LIST SDL1 ON SDL1.ITEM_CODE = EE.PS AND SDL1.DICT_CODE = 'PS' LEFT JOIN SYS_DATADICT_LIST SDL2 ON SDL2.ITEM_CODE = EEA.ASSET_TYPE AND SDL2.DICT_CODE = 'PINAN_ASSET_TYPE' LEFT JOIN SYS_DATADICT_LIST SDL3 ON SDL3.ITEM_CODE = EE.TRADE_MARKET AND SDL3.DICT_CODE = 'TRADE_PLACE' LEFT JOIN SYS_DATADICT_LIST SDL4 ON SDL4.ITEM_CODE = EEA.SETTLE_SPREED AND SDL4.DICT_CODE = 'ACCOUNT_SPEED' LEFT JOIN PTL_PORTFOLIO PP ON EE.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN (SELECT A.WORKFLOW_ID,A.TRADE_ID,ROW_NUMBER() OVER (PARTITION BY A.TRADE_ID ORDER BY A.UPDATE_TIME DESC) NUM FROM SYS_WFL_BUSINESS_LIST A) SWBL ON EE.ENTRUST_ID = SWBL.TRADE_ID AND NUM = 1 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN1 ON SWBL.WORKFLOW_ID = SWBN1.WORKFLOW_ID AND SWBN1.HIS_NO = 1 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN2 ON SWBL.WORKFLOW_ID = SWBN2.WORKFLOW_ID AND SWBN2.HIS_NO = 2 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN3 ON SWBL.WORKFLOW_ID = SWBN3.WORKFLOW_ID AND SWBN3.HIS_NO = 3 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN4 ON SWBL.WORKFLOW_ID = SWBN4.WORKFLOW_ID AND SWBN4.HIS_NO = 4 LEFT JOIN SYS_WFL_BUSINESS_NODE SWBN5 ON SWBL.WORKFLOW_ID = SWBN5.WORKFLOW_ID AND SWBN5.HIS_NO = 5 INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON EE.PORTFOLIO_ID = PPA.PORTFOLIO_ID WHERE EEA.ASSET_TYPE NOT IN ('F01','F07')
AND PPA.USER_ID = #{userId,jdbcType=VARCHAR}
AND (EE.ENTRUST_ID IN
null) OR EE.ENTRUST_ID IN (
